-- >>> 09_chat_conversations.sql
-- =============================================================================
-- 09  Conversations, messages, citations (message sources), feedback,
--     search and retrieval logs  (+ their RLS policies)
-- Spec refs: 6.8, 6.10, 10.2.4, 10.6 rule 8, FR-019, FR-119/120, FR-153..FR-162,
-- FR-226, FR-247.  Owner-scoped: only the owning user reads conversations,
-- messages, sources and personal search history.  Analytics use aggregates
-- (11_audit_analytics.sql); investigators use break-glass.
-- Partitioning by month (spec 10.5.2) is deferred until measured volume
-- requires it - see docs/database/DATABASE_DESIGN.md "Partitioning".
-- =============================================================================
CREATE TABLE IF NOT EXISTS rag.conversations (
  tenant_id       uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  conversation_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id         uuid NOT NULL,
  title           text NOT NULL DEFAULT 'New conversation',
  context         jsonb NOT NULL DEFAULT '{}'::jsonb,   -- product, jurisdiction, as_of_date, collections
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'deleted')),
  legal_hold      boolean NOT NULL DEFAULT false,
  retention_until date,
  message_count   integer NOT NULL DEFAULT 0,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  UNIQUE (tenant_id, conversation_id),
  FOREIGN KEY (tenant_id, user_id) REFERENCES iam.users (tenant_id, user_id)
);

CREATE TABLE IF NOT EXISTS rag.conversation_messages (
  tenant_id         uuid NOT NULL,
  message_id        uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  conversation_id   uuid NOT NULL,
  user_id           uuid NOT NULL,
  seq               integer NOT NULL,
  role              text NOT NULL CHECK (role IN ('user', 'assistant', 'notice')),
  content           text NOT NULL,                     -- protected column
  content_hash      text NOT NULL,
  answer_status     text CHECK (answer_status IN ('answered', 'abstained', 'blocked', 'error', 'needs_review')),
  evidence_strength text CHECK (evidence_strength IN ('high', 'medium', 'low', 'none')),
  rewritten_query   text,
  warnings          jsonb NOT NULL DEFAULT '[]'::jsonb,
  model_provider    text,
  model_name        text,
  prompt_version    text,
  guardrail_version text,
  rag_config_version integer,
  input_tokens      integer NOT NULL DEFAULT 0,
  output_tokens     integer NOT NULL DEFAULT 0,
  latency_ms        integer,
  correlation_id    text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, message_id),
  UNIQUE (conversation_id, seq),
  FOREIGN KEY (tenant_id, conversation_id) REFERENCES rag.conversations (tenant_id, conversation_id) ON DELETE CASCADE
);

-- Citations: link an answer to the chunk / version / page that supports it.
-- No FK to chunks: a chunk may be purged while past answers are retained (spec 10.3).
CREATE TABLE IF NOT EXISTS rag.message_sources (
  tenant_id     uuid NOT NULL,
  source_id     uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  message_id    uuid NOT NULL,
  user_id       uuid NOT NULL,
  ordinal       integer NOT NULL,
  chunk_id      uuid NOT NULL,
  document_id   uuid NOT NULL,
  version_id    uuid NOT NULL,
  title         text,
  section_path  text,
  clause_ref    text,
  page_from     integer,
  page_to       integer,
  score         real,
  verified      boolean NOT NULL DEFAULT false,
  quote_hash    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (message_id, ordinal),
  FOREIGN KEY (tenant_id, message_id) REFERENCES rag.conversation_messages (tenant_id, message_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS rag.feedback (
  tenant_id        uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  feedback_id      uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id          uuid NOT NULL,
  message_id       uuid,
  search_id        uuid,
  rating           smallint CHECK (rating IN (-1, 1)),
  category         text NOT NULL DEFAULT 'rating' CHECK (category IN
                     ('rating', 'incorrect', 'outdated', 'unsafe', 'missing_source', 'wrong_version', 'access', 'document_error', 'other')),
  comment          text,                               -- protected column
  severity         text NOT NULL DEFAULT 'low' CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  status           text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'triaged', 'in_progress', 'resolved', 'rejected')),
  assigned_to      uuid,
  resolution       text,
  golden_candidate boolean NOT NULL DEFAULT false,
  created_at       timestamptz NOT NULL DEFAULT now(),
  resolved_at      timestamptz,
  UNIQUE (tenant_id, feedback_id),
  FOREIGN KEY (tenant_id, user_id)    REFERENCES iam.users (tenant_id, user_id),
  FOREIGN KEY (tenant_id, message_id) REFERENCES rag.conversation_messages (tenant_id, message_id) ON DELETE SET NULL (message_id)
);

CREATE TABLE IF NOT EXISTS rag.search_logs (
  tenant_id         uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  search_id         uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id           uuid NOT NULL,
  department_id     uuid,
  conversation_id   uuid,
  message_id        uuid,
  mode              text NOT NULL CHECK (mode IN ('vector', 'fulltext', 'hybrid', 'chat')),
  query_hash        text NOT NULL,
  query_text        text,                              -- only when tenant policy allows (protected)
  filters           jsonb NOT NULL DEFAULT '{}'::jsonb,
  policy_scope_hash text NOT NULL,
  rag_config_version integer,
  result_count      integer NOT NULL DEFAULT 0,
  top_score         real,
  latency_ms        integer,
  cache_hit         boolean NOT NULL DEFAULT false,
  correlation_id    text,
  created_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, search_id),
  FOREIGN KEY (tenant_id, user_id) REFERENCES iam.users (tenant_id, user_id)
);

CREATE TABLE IF NOT EXISTS rag.retrieval_logs (
  tenant_id   uuid NOT NULL,
  retrieval_id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  search_id   uuid NOT NULL,
  user_id     uuid NOT NULL,
  stage       text NOT NULL CHECK (stage IN ('vector', 'fulltext', 'exact', 'fused', 'reranked', 'context')),
  rank        integer NOT NULL,
  chunk_id    uuid NOT NULL,
  document_id uuid NOT NULL,
  score       real,
  selected    boolean NOT NULL DEFAULT false,
  created_at  timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, search_id) REFERENCES rag.search_logs (tenant_id, search_id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS conversations_user   ON rag.conversations (tenant_id, user_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS messages_conv        ON rag.conversation_messages (tenant_id, conversation_id, seq);
CREATE INDEX IF NOT EXISTS messages_time        ON rag.conversation_messages (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS sources_message      ON rag.message_sources (tenant_id, message_id);
CREATE INDEX IF NOT EXISTS sources_version      ON rag.message_sources (tenant_id, version_id);
CREATE INDEX IF NOT EXISTS feedback_queue       ON rag.feedback (tenant_id, status, created_at);
CREATE INDEX IF NOT EXISTS feedback_message     ON rag.feedback (tenant_id, message_id);
CREATE INDEX IF NOT EXISTS search_logs_user     ON rag.search_logs (tenant_id, user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS search_logs_time     ON rag.search_logs (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS search_logs_corr     ON rag.search_logs (correlation_id);
CREATE INDEX IF NOT EXISTS retrieval_logs_search ON rag.retrieval_logs (tenant_id, search_id);
CREATE INDEX IF NOT EXISTS retrieval_logs_chunk ON rag.retrieval_logs (tenant_id, chunk_id);

DROP TRIGGER IF EXISTS trg_conversations_touch ON rag.conversations;
CREATE TRIGGER trg_conversations_touch BEFORE UPDATE ON rag.conversations FOR EACH ROW EXECUTE FUNCTION app.touch_updated_at();

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
SELECT app_admin.apply_tenant_rls(t::regclass) FROM unnest(ARRAY[
  'rag.conversations', 'rag.conversation_messages', 'rag.message_sources', 'rag.feedback',
  'rag.search_logs', 'rag.retrieval_logs']) AS t;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['rag.conversations', 'rag.conversation_messages', 'rag.message_sources',
                           'rag.search_logs', 'rag.retrieval_logs'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS owner_all ON %s', t);
    EXECUTE format($f$CREATE POLICY owner_all ON %s FOR ALL
        USING (app.mode_in('user') AND user_id = app.current_user_id())
        WITH CHECK (app.mode_in('user') AND user_id = app.current_user_id())$f$, t);
    EXECUTE format('DROP POLICY IF EXISTS worker_all ON %s', t);
    EXECUTE format($f$CREATE POLICY worker_all ON %s FOR ALL USING (app.mode_in('worker')) WITH CHECK (app.mode_in('worker'))$f$, t);
    EXECUTE format('DROP POLICY IF EXISTS break_glass_read ON %s', t);
    EXECUTE format($f$CREATE POLICY break_glass_read ON %s FOR SELECT USING (app.break_glass_active())$f$, t);
  END LOOP;
END $$;
DROP POLICY IF EXISTS owner_all ON rag.feedback;
CREATE POLICY owner_all ON rag.feedback FOR ALL
  USING (app.mode_in('user') AND user_id = app.current_user_id())
  WITH CHECK (app.mode_in('user') AND user_id = app.current_user_id());
DROP POLICY IF EXISTS reviewer_all ON rag.feedback;
CREATE POLICY reviewer_all ON rag.feedback FOR ALL
  USING (app.mode_in('tenant_admin', 'worker', 'auditor')) WITH CHECK (app.mode_in('tenant_admin', 'worker'));

GRANT SELECT, INSERT, UPDATE ON rag.conversations, rag.conversation_messages, rag.message_sources, rag.feedback,
                                rag.search_logs, rag.retrieval_logs TO rag_app;
GRANT DELETE ON rag.conversations, rag.conversation_messages, rag.message_sources TO rag_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON rag.conversations, rag.conversation_messages, rag.message_sources,
      rag.feedback, rag.search_logs, rag.retrieval_logs TO rag_worker;
GRANT SELECT ON rag.feedback TO rag_readonly;

-- >>> 10_ai_configuration.sql
-- =============================================================================
-- 10  Tenant AI and RAG configuration, prompt templates, guardrail events and
--     model usage records (+ RLS)
-- Spec refs: 6.11 (FR-169..FR-173, FR-176, FR-177), 6.9 (FR-151, FR-152),
-- 6.14 (FR-220, FR-221), 10.2.5, extension 7.7.
-- Configurations are versioned and immutable once superseded: a change inserts
-- a new version and flips is_active (rollback = re-activate an old version).
-- =============================================================================
CREATE TABLE IF NOT EXISTS ai.tenant_ai_configurations (
  tenant_id            uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  config_id            uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  version              integer NOT NULL,
  llm_provider         text NOT NULL DEFAULT 'local',
  chat_model           text NOT NULL DEFAULT 'extractive-v1',
  embedding_provider   text NOT NULL DEFAULT 'local',
  embedding_model      text NOT NULL DEFAULT 'hashing-v1',
  embedding_dimensions integer NOT NULL DEFAULT 384 CHECK (embedding_dimensions IN (256, 384, 512, 768, 1024, 1536, 3072)),
  reranker_provider    text NOT NULL DEFAULT 'local',
  reranker_model       text NOT NULL DEFAULT 'lexical-overlap-v1',
  rewrite_model        text,
  temperature          real NOT NULL DEFAULT 0.1 CHECK (temperature BETWEEN 0 AND 2),
  max_output_tokens    integer NOT NULL DEFAULT 800 CHECK (max_output_tokens BETWEEN 16 AND 16000),
  distance_metric      text NOT NULL DEFAULT 'cosine' CHECK (distance_metric IN ('cosine', 'inner_product', 'l2')),
  is_active            boolean NOT NULL DEFAULT false,
  change_reason        text,
  created_by           uuid,
  created_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, version)
);
CREATE UNIQUE INDEX IF NOT EXISTS ai_config_one_active ON ai.tenant_ai_configurations (tenant_id) WHERE is_active;

CREATE TABLE IF NOT EXISTS ai.tenant_rag_configurations (
  tenant_id          uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  config_id          uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  version            integer NOT NULL,
  chunking_strategy  text NOT NULL DEFAULT 'structure_aware' CHECK (chunking_strategy IN ('fixed', 'recursive', 'structure_aware')),
  chunk_size         integer NOT NULL DEFAULT 350 CHECK (chunk_size BETWEEN 64 AND 4000),     -- tokens
  chunk_overlap      integer NOT NULL DEFAULT 40  CHECK (chunk_overlap >= 0),
  parent_child       boolean NOT NULL DEFAULT true,
  vector_top_k       integer NOT NULL DEFAULT 30 CHECK (vector_top_k BETWEEN 1 AND 500),
  fts_top_k          integer NOT NULL DEFAULT 30 CHECK (fts_top_k BETWEEN 1 AND 500),
  exact_top_k        integer NOT NULL DEFAULT 10 CHECK (exact_top_k BETWEEN 0 AND 100),
  vector_weight      real NOT NULL DEFAULT 1.0 CHECK (vector_weight >= 0),
  fts_weight         real NOT NULL DEFAULT 1.0 CHECK (fts_weight >= 0),
  exact_weight       real NOT NULL DEFAULT 1.5 CHECK (exact_weight >= 0),
  rrf_k              integer NOT NULL DEFAULT 60 CHECK (rrf_k BETWEEN 1 AND 1000),
  rerank_enabled     boolean NOT NULL DEFAULT true,
  rerank_top_n       integer NOT NULL DEFAULT 20 CHECK (rerank_top_n BETWEEN 1 AND 200),
  final_top_k        integer NOT NULL DEFAULT 6 CHECK (final_top_k BETWEEN 1 AND 50),
  max_context_tokens integer NOT NULL DEFAULT 3000 CHECK (max_context_tokens BETWEEN 256 AND 128000),
  min_relevance      real NOT NULL DEFAULT 0.0 CHECK (min_relevance >= 0),
  hnsw_ef_search     integer NOT NULL DEFAULT 100 CHECK (hnsw_ef_search BETWEEN 10 AND 1000),
  citation_required  boolean NOT NULL DEFAULT true,
  query_rewriting    boolean NOT NULL DEFAULT true,
  guardrails         jsonb NOT NULL DEFAULT '{"prompt_injection": "block", "pii_output": "mask", "regulated_decision": "block"}'::jsonb,
  is_active          boolean NOT NULL DEFAULT false,
  change_reason      text,
  created_by         uuid,
  created_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, version),
  CHECK (chunk_overlap < chunk_size)
);
CREATE UNIQUE INDEX IF NOT EXISTS rag_config_one_active ON ai.tenant_rag_configurations (tenant_id) WHERE is_active;

-- Tenant-specific provider credentials (only when the platform allows override).
CREATE TABLE IF NOT EXISTS ai.tenant_provider_credentials (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  credential_id  uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  provider_code  text NOT NULL,
  base_url       text,
  api_key_enc    text,
  api_key_last4  text,
  created_by     uuid,
  created_at     timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, provider_code)
);

CREATE TABLE IF NOT EXISTS ai.prompt_templates (
  tenant_id     uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  template_id   uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  name          text NOT NULL,
  purpose       text NOT NULL CHECK (purpose IN ('answer', 'rewrite', 'judge', 'summarise')),
  version       integer NOT NULL,
  template      text NOT NULL,
  status        text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'active', 'retired')),
  created_by    uuid,
  approved_by   uuid,
  approved_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, name, version),
  CHECK (approved_by IS NULL OR approved_by <> created_by)      -- approver differs from author (FR-171)
);

CREATE TABLE IF NOT EXISTS ai.guardrail_events (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  event_id       uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id        uuid,
  conversation_id uuid,
  message_id     uuid,
  stage          text NOT NULL CHECK (stage IN ('ingestion', 'input', 'evidence', 'output')),
  rule_id        text NOT NULL,
  rule_version   text NOT NULL DEFAULT '1',
  decision       text NOT NULL CHECK (decision IN ('allow', 'block', 'sanitise', 'mask', 'abstain', 'alert', 'quarantine')),
  severity       text NOT NULL DEFAULT 'low' CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  category       text NOT NULL,
  correlation_id text,
  detail         jsonb NOT NULL DEFAULT '{}'::jsonb,         -- match metadata only, never raw content
  occurred_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS ai.tenant_model_usage (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  usage_id       uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id        uuid,
  department_id  uuid,
  purpose        text NOT NULL CHECK (purpose IN ('chat', 'embedding', 'rerank', 'rewrite', 'judge', 'ingestion_embedding')),
  provider       text NOT NULL,
  model          text NOT NULL,
  input_tokens   integer NOT NULL DEFAULT 0,
  output_tokens  integer NOT NULL DEFAULT 0,
  latency_ms     integer,
  estimated_cost numeric(14,6) NOT NULL DEFAULT 0,       -- estimate from catalogue pricing
  status         text NOT NULL DEFAULT 'success' CHECK (status IN ('success', 'error', 'fallback')),
  correlation_id text,
  created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS guardrail_rule    ON ai.guardrail_events (tenant_id, rule_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS guardrail_corr    ON ai.guardrail_events (correlation_id);
CREATE INDEX IF NOT EXISTS model_usage_time  ON ai.tenant_model_usage (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS model_usage_model ON ai.tenant_model_usage (tenant_id, model, created_at DESC);

SELECT app_admin.apply_tenant_rls(t::regclass) FROM unnest(ARRAY[
  'ai.tenant_ai_configurations', 'ai.tenant_rag_configurations', 'ai.tenant_provider_credentials',
  'ai.prompt_templates', 'ai.guardrail_events', 'ai.tenant_model_usage']) AS t;

-- Configuration: every tenant context may read the active configuration (the RAG
-- pipeline needs it); administration writes.  Platform provisioning seeds defaults.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ai.tenant_ai_configurations', 'ai.tenant_rag_configurations', 'ai.prompt_templates'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS tenant_read ON %s', t);
    EXECUTE format($f$CREATE POLICY tenant_read ON %s FOR SELECT
                      USING (app.mode_in('user', 'tenant_admin', 'auditor', 'worker', 'platform_provisioning'))$f$, t);
    EXECUTE format('DROP POLICY IF EXISTS admin_write ON %s', t);
    EXECUTE format($f$CREATE POLICY admin_write ON %s FOR ALL
                      USING (app.mode_in('tenant_admin', 'platform_provisioning'))
                      WITH CHECK (app.mode_in('tenant_admin', 'platform_provisioning'))$f$, t);
  END LOOP;
END $$;
DROP POLICY IF EXISTS cred_admin ON ai.tenant_provider_credentials;
CREATE POLICY cred_admin ON ai.tenant_provider_credentials FOR ALL
  USING (app.mode_in('tenant_admin', 'worker', 'platform_provisioning', 'user'))
  WITH CHECK (app.mode_in('tenant_admin', 'platform_provisioning'));

-- Events / usage: any tenant context appends; admins, auditors and workers read.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ai.guardrail_events', 'ai.tenant_model_usage'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS append ON %s', t);
    EXECUTE format($f$CREATE POLICY append ON %s FOR INSERT
                      WITH CHECK (app.mode_in('user', 'tenant_admin', 'worker', 'auditor'))$f$, t);
    EXECUTE format('DROP POLICY IF EXISTS admin_read ON %s', t);
    EXECUTE format($f$CREATE POLICY admin_read ON %s FOR SELECT USING (app.mode_in('tenant_admin', 'auditor', 'worker'))$f$, t);
  END LOOP;
END $$;

GRANT SELECT, INSERT, UPDATE ON ai.tenant_ai_configurations, ai.tenant_rag_configurations,
                                ai.tenant_provider_credentials, ai.prompt_templates TO rag_app;
GRANT DELETE ON ai.tenant_provider_credentials TO rag_app;
GRANT SELECT, INSERT ON ai.guardrail_events, ai.tenant_model_usage TO rag_app, rag_worker;
GRANT SELECT ON ai.tenant_ai_configurations, ai.tenant_rag_configurations, ai.tenant_provider_credentials,
                ai.prompt_templates TO rag_worker;
GRANT SELECT ON ai.guardrail_events, ai.tenant_model_usage, ai.tenant_ai_configurations,
                ai.tenant_rag_configurations TO rag_readonly;

-- >>> 11_audit_analytics.sql
-- =============================================================================
-- 11  Audit (append-only, hash-chained) and analytics aggregates (+ RLS)
-- Spec refs: 15 (15 audit categories), FR-226..FR-230, NFR-057, NFR-075,
-- FR-216..FR-224, extension section 10.
-- =============================================================================
CREATE TABLE IF NOT EXISTS audit.tenant_audit_logs (
  tenant_id        uuid NOT NULL,                 -- logical reference only (records outlive entities)
  event_id         uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  seq              bigint GENERATED ALWAYS AS IDENTITY,
  occurred_at      timestamptz NOT NULL DEFAULT clock_timestamp(),
  category         text NOT NULL CHECK (category IN
                     ('authentication', 'authorization', 'document_access', 'search', 'retrieval', 'answer',
                      'model_call', 'prompt', 'guardrail', 'feedback', 'ingestion', 'document_update',
                      'document_deletion', 'configuration', 'administration', 'security')),
  event_type       text NOT NULL,
  outcome          text NOT NULL DEFAULT 'success' CHECK (outcome IN ('success', 'failure', 'denied')),
  actor_type       text NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user', 'service', 'platform_admin', 'system')),
  actor_user_id    uuid,
  actor_account_id uuid,
  resource_type    text,
  resource_id      text,
  correlation_id   text,
  source_ip        inet,
  detail           jsonb NOT NULL DEFAULT '{}'::jsonb,   -- identifiers and hashes, never sensitive content
  prev_hash        text,
  hash             text
);
CREATE INDEX IF NOT EXISTS audit_tenant_time     ON audit.tenant_audit_logs (tenant_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_tenant_category ON audit.tenant_audit_logs (tenant_id, category, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_tenant_actor    ON audit.tenant_audit_logs (tenant_id, actor_user_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_corr            ON audit.tenant_audit_logs (tenant_id, correlation_id);
CREATE INDEX IF NOT EXISTS audit_seq             ON audit.tenant_audit_logs (tenant_id, seq);

CREATE TABLE IF NOT EXISTS audit.chain_heads (
  chain_key  text PRIMARY KEY,           -- tenant uuid, or 'platform'
  last_hash  text NOT NULL,
  last_seq   bigint NOT NULL DEFAULT 0,
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Hash chain (FR-229): each event's hash covers the previous hash and the
-- event's immutable fields.  The trigger serialises writers per chain with a
-- row lock on the chain head.  SECURITY DEFINER (owner rag_audit_fn) so that
-- services need no access to chain_heads; search_path pinned.
CREATE OR REPLACE FUNCTION audit.chain_hash() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  v_key  text;
  v_prev text;
BEGIN
  IF TG_TABLE_NAME = 'tenant_audit_logs' THEN
    v_key := NEW.tenant_id::text;
  ELSE
    v_key := 'platform';
  END IF;
  INSERT INTO audit.chain_heads (chain_key, last_hash) VALUES (v_key, 'GENESIS') ON CONFLICT (chain_key) DO NOTHING;
  SELECT last_hash INTO v_prev FROM audit.chain_heads WHERE chain_key = v_key FOR UPDATE;
  NEW.prev_hash := v_prev;
  IF TG_TABLE_NAME = 'tenant_audit_logs' THEN
    NEW.hash := encode(public.digest(concat_ws('|', v_prev, NEW.event_id::text, NEW.tenant_id::text,
                  to_char(NEW.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'), NEW.category,
                  NEW.event_type, NEW.outcome, coalesce(NEW.actor_user_id::text, ''),
                  coalesce(NEW.resource_type, ''), coalesce(NEW.resource_id, ''), NEW.detail::text), 'sha256'), 'hex');
  ELSE
    NEW.hash := encode(public.digest(concat_ws('|', v_prev, NEW.event_id::text, coalesce(NEW.target_tenant_id::text, ''),
                  to_char(NEW.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'), NEW.category,
                  NEW.action, NEW.outcome, coalesce(NEW.actor_account_id::text, ''),
                  coalesce(NEW.target_type, ''), coalesce(NEW.target_id, ''), NEW.detail::text), 'sha256'), 'hex');
  END IF;
  UPDATE audit.chain_heads SET last_hash = NEW.hash, last_seq = last_seq + 1, updated_at = now() WHERE chain_key = v_key;
  RETURN NEW;
END $$;
GRANT USAGE, CREATE ON SCHEMA audit TO rag_audit_fn;
ALTER FUNCTION audit.chain_hash() OWNER TO rag_audit_fn;
REVOKE CREATE ON SCHEMA audit FROM rag_audit_fn;
REVOKE ALL ON FUNCTION audit.chain_hash() FROM PUBLIC;

DROP TRIGGER IF EXISTS trg_tenant_audit_chain ON audit.tenant_audit_logs;
CREATE TRIGGER trg_tenant_audit_chain BEFORE INSERT ON audit.tenant_audit_logs
  FOR EACH ROW EXECUTE FUNCTION audit.chain_hash();
DROP TRIGGER IF EXISTS trg_platform_audit_chain ON platform.platform_audit_logs;
CREATE TRIGGER trg_platform_audit_chain BEFORE INSERT ON platform.platform_audit_logs
  FOR EACH ROW EXECUTE FUNCTION audit.chain_hash();

-- Immutability guard even for the owner role: updates and deletes are refused.
CREATE OR REPLACE FUNCTION audit.refuse_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit records are append-only' USING ERRCODE = 'insufficient_privilege'; END $$;
DROP TRIGGER IF EXISTS trg_tenant_audit_immutable ON audit.tenant_audit_logs;
CREATE TRIGGER trg_tenant_audit_immutable BEFORE UPDATE OR DELETE ON audit.tenant_audit_logs
  FOR EACH ROW EXECUTE FUNCTION audit.refuse_mutation();
DROP TRIGGER IF EXISTS trg_platform_audit_immutable ON platform.platform_audit_logs;
CREATE TRIGGER trg_platform_audit_immutable BEFORE UPDATE OR DELETE ON platform.platform_audit_logs
  FOR EACH ROW EXECUTE FUNCTION audit.refuse_mutation();
-- TRUNCATE bypasses row triggers, so it gets its own statement-level guard
-- (blocks the owner role too; only an explicit, audited DBA change can drop it).
DROP TRIGGER IF EXISTS trg_tenant_audit_no_truncate ON audit.tenant_audit_logs;
CREATE TRIGGER trg_tenant_audit_no_truncate BEFORE TRUNCATE ON audit.tenant_audit_logs
  FOR EACH STATEMENT EXECUTE FUNCTION audit.refuse_mutation();
DROP TRIGGER IF EXISTS trg_platform_audit_no_truncate ON platform.platform_audit_logs;
CREATE TRIGGER trg_platform_audit_no_truncate BEFORE TRUNCATE ON platform.platform_audit_logs
  FOR EACH STATEMENT EXECUTE FUNCTION audit.refuse_mutation();

ALTER TABLE audit.chain_heads ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit.chain_heads FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS chain_fn ON audit.chain_heads;
CREATE POLICY chain_fn ON audit.chain_heads FOR ALL TO rag_audit_fn USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA audit TO rag_audit_fn;
GRANT SELECT, INSERT, UPDATE ON audit.chain_heads TO rag_audit_fn;

-- Integrity verification (FR-229): recomputes the chain for the current tenant.
CREATE OR REPLACE FUNCTION audit.verify_tenant_chain() RETURNS TABLE (ok boolean, checked bigint, first_broken_event uuid)
LANGUAGE plpgsql STABLE AS $$
DECLARE
  r record; v_prev text := 'GENESIS'; v_hash text; n bigint := 0;
BEGIN
  FOR r IN SELECT * FROM audit.tenant_audit_logs WHERE tenant_id = app.current_tenant_id() ORDER BY seq LOOP
    n := n + 1;
    v_hash := encode(public.digest(concat_ws('|', v_prev, r.event_id::text, r.tenant_id::text,
                to_char(r.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'), r.category,
                r.event_type, r.outcome, coalesce(r.actor_user_id::text, ''),
                coalesce(r.resource_type, ''), coalesce(r.resource_id, ''), r.detail::text), 'sha256'), 'hex');
    IF r.prev_hash IS DISTINCT FROM v_prev OR r.hash IS DISTINCT FROM v_hash THEN
      RETURN QUERY SELECT false, n, r.event_id; RETURN;
    END IF;
    v_prev := r.hash;
  END LOOP;
  RETURN QUERY SELECT true, n, NULL::uuid;
END $$;

SELECT app_admin.apply_tenant_rls('audit.tenant_audit_logs'::regclass);
DROP POLICY IF EXISTS audit_append ON audit.tenant_audit_logs;
CREATE POLICY audit_append ON audit.tenant_audit_logs FOR INSERT
  WITH CHECK (app.mode_in('user', 'tenant_admin', 'auditor', 'worker', 'platform_provisioning', 'break_glass'));
DROP POLICY IF EXISTS audit_read ON audit.tenant_audit_logs;
CREATE POLICY audit_read ON audit.tenant_audit_logs FOR SELECT USING (app.mode_in('tenant_admin', 'auditor'));
GRANT INSERT ON audit.tenant_audit_logs TO rag_app, rag_worker;
GRANT SELECT ON audit.tenant_audit_logs TO rag_app, rag_readonly;
-- Deliberately NO UPDATE / DELETE grants on audit tables for any service role.

-- -----------------------------------------------------------------------------
-- Analytics aggregates, produced by the scheduled aggregation job per tenant
-- (one validated tenant context per tenant).  Dashboards read these instead of
-- scanning conversations / documents on every page load.
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ops.tenant_usage_daily (
  tenant_id            uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  usage_date           date NOT NULL,
  searches             integer NOT NULL DEFAULT 0,
  chats                integer NOT NULL DEFAULT 0,
  conversations_started integer NOT NULL DEFAULT 0,
  ai_requests          integer NOT NULL DEFAULT 0,
  input_tokens         bigint  NOT NULL DEFAULT 0,
  output_tokens        bigint  NOT NULL DEFAULT 0,
  estimated_cost       numeric(14,6) NOT NULL DEFAULT 0,
  documents_ingested   integer NOT NULL DEFAULT 0,
  ingestion_failures   integer NOT NULL DEFAULT 0,
  active_users         integer NOT NULL DEFAULT 0,
  avg_search_latency_ms integer,
  avg_llm_latency_ms   integer,
  abstentions          integer NOT NULL DEFAULT 0,
  feedback_positive    integer NOT NULL DEFAULT 0,
  feedback_negative    integer NOT NULL DEFAULT 0,
  guardrail_blocks     integer NOT NULL DEFAULT 0,
  documents_total      integer NOT NULL DEFAULT 0,
  chunks_total         bigint  NOT NULL DEFAULT 0,
  storage_bytes        bigint  NOT NULL DEFAULT 0,
  users_total          integer NOT NULL DEFAULT 0,
  computed_at          timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, usage_date)
);

CREATE TABLE IF NOT EXISTS ops.department_usage_daily (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  usage_date     date NOT NULL,
  department_id  uuid NOT NULL,
  searches       integer NOT NULL DEFAULT 0,
  chats          integer NOT NULL DEFAULT 0,
  input_tokens   bigint  NOT NULL DEFAULT 0,
  output_tokens  bigint  NOT NULL DEFAULT 0,
  estimated_cost numeric(14,6) NOT NULL DEFAULT 0,
  active_users   integer NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, usage_date, department_id)
);

CREATE TABLE IF NOT EXISTS ops.user_activity_daily (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  usage_date     date NOT NULL,
  user_id        uuid NOT NULL,
  searches       integer NOT NULL DEFAULT 0,
  chats          integer NOT NULL DEFAULT 0,
  tokens         bigint  NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, usage_date, user_id)
);

-- tenant_usage_daily holds no user- or content-level data: platform readers may
-- see all tenants' aggregates; tenants see their own.
ALTER TABLE ops.tenant_usage_daily ENABLE ROW LEVEL SECURITY;
ALTER TABLE ops.tenant_usage_daily FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS usage_read ON ops.tenant_usage_daily;
CREATE POLICY usage_read ON ops.tenant_usage_daily FOR SELECT USING (
  (tenant_id = app.current_tenant_id() AND app.mode_in('tenant_admin', 'auditor', 'worker')) OR app.is_platform_reader());
DROP POLICY IF EXISTS usage_write ON ops.tenant_usage_daily;
CREATE POLICY usage_write ON ops.tenant_usage_daily FOR ALL
  USING (tenant_id = app.current_tenant_id() AND app.mode_in('worker'))
  WITH CHECK (tenant_id = app.current_tenant_id() AND app.mode_in('worker'));

SELECT app_admin.apply_tenant_rls(t::regclass) FROM unnest(ARRAY['ops.department_usage_daily', 'ops.user_activity_daily']) AS t;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ops.department_usage_daily', 'ops.user_activity_daily'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS admin_read ON %s', t);
    EXECUTE format($f$CREATE POLICY admin_read ON %s FOR SELECT USING (app.mode_in('tenant_admin', 'auditor', 'worker'))$f$, t);
    EXECUTE format('DROP POLICY IF EXISTS worker_write ON %s', t);
    EXECUTE format($f$CREATE POLICY worker_write ON %s FOR ALL USING (app.mode_in('worker')) WITH CHECK (app.mode_in('worker'))$f$, t);
  END LOOP;
END $$;

GRANT SELECT ON ops.tenant_usage_daily, ops.department_usage_daily, ops.user_activity_daily TO rag_app, rag_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON ops.tenant_usage_daily, ops.department_usage_daily, ops.user_activity_daily TO rag_worker;

-- >>> 12_evaluation.sql
-- =============================================================================
-- 12  RAG evaluation datasets, questions, runs and results (+ RLS)
-- Spec refs: 6.13 (FR-200..FR-215), 14, 10.2.5 (#27, #28).
-- =============================================================================
CREATE TABLE IF NOT EXISTS eval.evaluation_datasets (
  tenant_id   uuid NOT NULL REFERENCES platform.tenants(tenant_id) ON DELETE RESTRICT,
  dataset_id  uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  name        text NOT NULL,
  version     integer NOT NULL DEFAULT 1,
  purpose     text NOT NULL DEFAULT 'retrieval' CHECK (purpose IN ('retrieval', 'generation', 'safety', 'access', 'regression')),
  description text,
  status      text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'retired')),
  created_by  uuid,
  approved_by uuid,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, dataset_id),
  UNIQUE (tenant_id, name, version),
  CHECK (approved_by IS NULL OR approved_by <> created_by)
);

CREATE TABLE IF NOT EXISTS eval.evaluation_questions (
  tenant_id            uuid NOT NULL,
  question_id          uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  dataset_id           uuid NOT NULL,
  question             text NOT NULL,
  expected_answer      text,
  expected_document_ids uuid[] NOT NULL DEFAULT '{}',
  expected_chunk_ids   uuid[] NOT NULL DEFAULT '{}',
  answerable           boolean NOT NULL DEFAULT true,
  category             text,
  line_of_business     text,
  jurisdiction         text,
  difficulty           text CHECK (difficulty IS NULL OR difficulty IN ('easy', 'medium', 'hard')),
  is_critical          boolean NOT NULL DEFAULT false,
  created_at           timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, question_id),
  FOREIGN KEY (tenant_id, dataset_id) REFERENCES eval.evaluation_datasets (tenant_id, dataset_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS eval.evaluation_runs (
  tenant_id       uuid NOT NULL,
  run_id          uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  dataset_id      uuid NOT NULL,
  status          text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed')),
  mode            text NOT NULL DEFAULT 'retrieval' CHECK (mode IN ('retrieval', 'end_to_end')),
  k               integer NOT NULL DEFAULT 10,
  config_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,   -- AI + RAG config versions, models, index generation (FR-213)
  evaluator_user_id uuid,                               -- persona whose permissions the run uses
  summary         jsonb NOT NULL DEFAULT '{}'::jsonb,
  gate_passed     boolean,
  initiated_by    uuid,
  started_at      timestamptz,
  finished_at     timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, run_id),
  FOREIGN KEY (tenant_id, dataset_id) REFERENCES eval.evaluation_datasets (tenant_id, dataset_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS eval.evaluation_results (
  tenant_id          uuid NOT NULL,
  result_id          uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  run_id             uuid NOT NULL,
  question_id        uuid NOT NULL,
  retrieved_chunk_ids uuid[] NOT NULL DEFAULT '{}',
  retrieved_document_ids uuid[] NOT NULL DEFAULT '{}',
  metrics            jsonb NOT NULL DEFAULT '{}'::jsonb,
  answer_status      text,
  passed             boolean,
  latency_ms         integer,
  created_at         timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, run_id)      REFERENCES eval.evaluation_runs (tenant_id, run_id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, question_id) REFERENCES eval.evaluation_questions (tenant_id, question_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS eval_results_run ON eval.evaluation_results (tenant_id, run_id);
CREATE INDEX IF NOT EXISTS eval_runs_dataset ON eval.evaluation_runs (tenant_id, dataset_id, created_at DESC);

SELECT app_admin.apply_tenant_rls(t::regclass) FROM unnest(ARRAY[
  'eval.evaluation_datasets', 'eval.evaluation_questions', 'eval.evaluation_runs', 'eval.evaluation_results']) AS t;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['eval.evaluation_datasets', 'eval.evaluation_questions', 'eval.evaluation_runs',
                           'eval.evaluation_results'] LOOP
    EXECUTE format('DROP POLICY IF EXISTS evaluator_all ON %s', t);
    EXECUTE format($f$CREATE POLICY evaluator_all ON %s FOR ALL
                      USING (app.mode_in('tenant_admin', 'worker', 'auditor'))
                      WITH CHECK (app.mode_in('tenant_admin', 'worker'))$f$, t);
  END LOOP;
END $$;
GRANT SELECT, INSERT, UPDATE ON eval.evaluation_datasets, eval.evaluation_questions, eval.evaluation_runs,
                                eval.evaluation_results TO rag_app;
GRANT DELETE ON eval.evaluation_questions TO rag_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON eval.evaluation_datasets, eval.evaluation_questions, eval.evaluation_runs,
      eval.evaluation_results TO rag_worker;
GRANT SELECT ON eval.evaluation_datasets, eval.evaluation_runs, eval.evaluation_results TO rag_readonly;

COMMIT;
